"%% trimnl_02 : Nonlinear climb + coordinated-turn trim (3 coupled equations)
% Unknowns: x = [alpha (rad); T (lbf); delta_e (rad)]
% Equations:
%   1) q*S*CL*cos(phi) + T*sin(alpha+i_T) - W*cos(gamma)      = 0
%   2) T*cos(alpha+i_T) - q*S*CD - W*sin(gamma)               = 0
%   3) q*S*cbar*(Cm0+Cma*alpha+Cmde*delta_e) + T*sin(i_T)*z_T = 0

clear; clc;

% ---------------- given data ----------------
W    = 280000.0;          % weight, lbf
S    = 2730.0;            % wing area, ft^2
h    = 35000.0;           % altitude, ft
V    = 780.0;             % true airspeed, ft/s
gam  = 5.0*pi/180;        % climb angle, rad
phi  = 40.0*pi/180;       % bank angle, rad

CL0  = 0.18;  CLa  = 5.6;   CLde = 0.3;     % 1/rad
CD0  = 0.019; kD   = 0.045;                 % parabolic drag
rho0 = 0.0023769;                           % slug/ft^3

iT   = 3.0*pi/180;        % thrust line incidence, rad
zT   = 2.2;               % thrust perpendicular arm, ft

Cm0  = 0.025; Cma = -0.34; Cmde = -0.9;     % 1/rad
cbar = 19.5;              % mean chord, ft

% ---------------- atmosphere & dynamics ----------------
rho = rho0*exp(-h/23800);
q   = 0.5*rho*V^2;

CLf = @(a,de) CL0 + CLa*a + CLde*de;
CDf = @(a,de) CD0 + kD*CLf(a,de)^2;

F = @(x) [ q*S*CLf(x(1),x(3))*cos(phi) + x(2)*sin(x(1)+iT) - W*cos(gam);
           x(2)*cos(x(1)+iT) - q*S*CDf(x(1),x(3)) - W*sin(gam);
           q*S*cbar*(Cm0 + Cma*x(1) + Cmde*x(3)) + x(2)*sin(iT)*zT ];

% ---------------- damped Newton with numerical Jacobian ----------------
guesses = [ 6.0*pi/180  45000.0  -0.7*pi/180;
            4.0*pi/180  40000.0  -1.0*pi/180;
            8.0*pi/180  50000.0   0.0        ];
tol   = 1e-12;
maxit = 200;
x     = guesses(1,:)';
converged = false;

for gsel = 1:size(guesses,1)
    x = guesses(gsel,:)';
    for it = 1:maxit
        Fx  = F(x);
        nFx = norm(Fx,inf);

        % numerical Jacobian (central-free forward differences)
        J = zeros(3,3);
        for j = 1:3
            d = 1e-7*max(abs(x(j)),1.0);
            e = zeros(3,1); e(j) = d;
            J(:,j) = (F(x+e) - Fx)/d;
        end

        step = -J\Fx;

        % damping: halve step until residual norm decreases
        lam = 1.0;
        for ls = 1:50
            xt = x + lam*step;
            if norm(F(xt),inf) < nFx, break; end
            lam = 0.5*lam;
        end
        x = x + lam*step;

        if norm(lam*step,inf) < tol && norm(F(x),inf) < 1e-6
            converged = true; break;
        end
    end
    if converged, break; end
end

if ~converged
    warning('Newton iteration did not fully converge; using last iterate.');
end

% ---------------- results ----------------
alpha_trim_deg   = x(1)*180/pi;
thrust_lbf       = x(2);
delta_e_trim_deg = x(3)*180/pi;
load_factor      = cos(gam)/cos(phi);

result = struct( ...
    'alpha_trim_deg',   alpha_trim_deg, ...
    'thrust_lbf',       thrust_lbf, ...
    'delta_e_trim_deg', delta_e_trim_deg, ...
    'load_factor',      load_factor);

fid = fopen('result.json','w');
fwrite(fid, jsonencode(result));
fclose(fid);

fprintf('Residual check (should be ~0): [%g %g %g]\n', F(x));
fprintf('alpha_trim = %.6f deg\n', alpha_trim_deg);
fprintf('thrust     = %.2f lbf\n',  thrust_lbf);
fprintf('delta_e    = %.6f deg\n', delta_e_trim_deg);
fprintf('n          = %.6f\n',     load_factor);"
